using System;using System.IO;using System.Linq;using System.Reflection;using UnityEditor;using UnityEngine;using EchoSphere.Runtime;using EchoSphere.Presentation;
public static class HomeScreenRenderCheck {
 public static object Main(){const BindingFlags f=BindingFlags.Public|BindingFlags.NonPublic|BindingFlags.Instance;var r=UnityEngine.Object.FindObjectsByType<EchoSphereRuntime>().First(x=>x.enabled);var field=typeof(EchoSphereRuntime).GetField("_nativeMenuState",f);var old=(NativeMainMenuView.State)field.GetValue(r);field.SetValue(r,new NativeMainMenuView.State(old.Russian,old.Name,old.CharacterName,old.CharacterRole,old.Difficulty,old.DifficultyTitle,old.NamePlaceholder,old.ShopTitle,old.LeaderboardTitle,old.AchievementsTitle,old.SettingsTitle,1234));int last=-1,frames=0;EditorApplication.CallbackFunction tick=null;Application.runInBackground=true;tick=()=>{EditorApplication.QueuePlayerLoopUpdate();if(last==Time.frameCount)return;last=Time.frameCount;if(++frames<24)return;EditorApplication.update-=tick;string status="PASS",error=null;Texture2D image=null;try{image=ScreenCapture.CaptureScreenshotAsTexture();Directory.CreateDirectory("Library/menu-archive");File.WriteAllBytes("Library/menu-archive/home-real-screen.png",image.EncodeToPNG());var screen=(NativeMainMenuScreen)typeof(EchoSphereRuntime).GetField("_nativeMainMenuScreen",f).GetValue(r);var view=screen.View;var button=UnityEngine.UIElements.UQueryExtensions.Q<UnityEngine.UIElements.VisualElement>(view.Root,"nav-0");var bounds=button.worldBound;var panel=view.Root.panel.visualTree.worldBound;float sx=image.width/panel.width,sy=image.height/panel.height;var color=image.GetPixel(Mathf.Clamp((int)((bounds.xMin-panel.xMin+3)*sx),0,image.width-1),Mathf.Clamp(image.height-(int)((bounds.yMin-panel.yMin+3)*sy),0,image.height-1));if(color.r>.8f&&color.g>.8f&&color.b>.8f)throw new Exception("White footer on actual screen");}catch(Exception e){status="FAIL";error=e.ToString();}finally{field.SetValue(r,old);if(image!=null)UnityEngine.Object.DestroyImmediate(image);File.WriteAllText("Library/menu-archive/home-screen.json",Newtonsoft.Json.JsonConvert.SerializeObject(new{status,error,scope="actual Game view render with temporary resume button; original display model restored, no save changes"}));}};EditorApplication.update+=tick;return new{status="queued"};}
}